const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.2520, -29.9027]).buffer(10000); // 10km buffer around La Serena

  // Get current year (assuming 2024, but adjust based on data availability)
  const currentYear = 2024;
  const currentStart = currentYear + '-01-01';
  const currentEnd = currentYear + '-07-07';

  const histStart = '1990-01-01';
  const histEnd = '2020-07-07';

  // 2. Data Acquisition - CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Current year YTD precipitation
  const currentYTD = chirps
    .filterDate(currentStart, currentEnd)
    .filterBounds(laSerena);

  // Historical YTD precipitation (1990-2020)
  const histYTD = chirps
    .filterDate(histStart, histEnd)
    .filterBounds(laSerena);

  // Check collection sizes
  const currentSize = currentYTD.size().getInfo();
  const histSize = histYTD.size().getInfo();

  console.log(`Current YTD images: ${currentSize}`);
  console.log(`Historical YTD images: ${histSize}`);

  if (currentSize === 0 || histSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation
  const currentSum = currentYTD.sum();
  const histMean = histYTD.mean();

  // Check valid pixels
  const currentCount = currentSum.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const histCount = histMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Current valid pixels: ${currentCount}`);
  console.log(`Historical valid pixels: ${histCount}`);

  if (currentCount === 0 || histCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation values
  const currentPrecip = currentSum.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const histPrecip = histMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Current YTD precip: ${currentPrecip?.toFixed(2)} mm`);
  console.log(`Historical mean YTD precip: ${histPrecip?.toFixed(2)} mm`);

  // 5. Validation & Final Answer
  if (currentPrecip === null || histPrecip === null || 
      isNaN(currentPrecip) || isNaN(histPrecip) || histPrecip === 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  const deficitPercent = ((currentPrecip - histPrecip) / histPrecip) * 100;
  console.log(`Deficit percentage: ${deficitPercent?.toFixed(1)}%`);

  if (deficitPercent < -40) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
